'use strict';
// Модуль «Сотрудники»
/* ═════════════ Сотрудники ═════════════ */
function staffTabs(){return [{id:'list',label:'Сотрудники',icon:'users',count:EMP.filter(e=>e.active).length},can('staff')?{id:'roles',label:'Роли',icon:'shield',count:ROLES.length}:null,can('staff')&&feat('accounts')&&feat('taxpay')?{id:'bonus',label:'Списания в бонус',icon:'gift'}:null]}
function staffAdd(){return !can('staff')?[]:[{label:'Сотрудник',icon:'user',run:empAddDlg},{label:'Роль',icon:'shield',run:roleAddDlg}]}
const empStats=e=>{const cps=CPS.filter(c=>c.resp===e.id&&!c.archived);const rs=REPORTS.filter(r=>!r.superseded&&r.resp===e.id);return {cps:cps.length,open:rs.filter(r=>OPEN.has(r.status)).length,over:rs.filter(r=>r.overdue).length,tasks:TASKS.filter(t=>t.exec===e.id&&taskOpen(t)).length}};
function renderStaff(body,tab,fresh){
  if(tab==='list'){body.innerHTML=(EMP.length===1?`<div class="note fe-note">${ic('users')}<span class="grow">Пока в организации только вы. Добавьте бухгалтеров: каждому — свой логин, роль и закреплённые контрагенты.</span><button class="btn cta sm" id="st-first">${ic('plus','sm')}Добавить сотрудника</button></div>`:'')+'<div id="sg"></div>';if($('#st-first',body))$('#st-first',body).onclick=empAddDlg;grid($('#sg',body),{id:'staff',cols:[
    {key:'fio',label:'ФИО',type:'text',w:270,val:e=>e.fio,html:e=>`<span class="row" style="flex-wrap:nowrap;gap:9px"><span class="av round" style="width:26px;height:26px;font-size:10.5px">${initials(e.fio)}</span><span class="strong" style="overflow:hidden;text-overflow:ellipsis">${esc(e.fio)}</span></span>`},
    // Порядок по ТЗ («Столбцы, видимые по умолчанию»): ФИО, роль, телефон, контрагентов, просрочено отчётов, статус, уровень знаний; остальные — в меню «Столбцы» (решение заказчика 26.10.2026)
    {key:'role',label:'Роль',type:'enum',w:170,val:e=>ROLES.find(r=>r.id===e.role).name},{key:'phone',label:'Телефон',type:'text',w:160,val:e=>fmtPhone(e.phone),cls:'mono'},
    {key:'cps',label:'Контрагентов',type:'int',w:120,num:true,val:e=>empStats(e).cps},{key:'over',label:'Просрочено',type:'int',w:110,num:true,val:e=>empStats(e).over,html:e=>{const n=empStats(e).over;return n?`<span class="pill red sm">${n}</span>`:'<span class="faint">0</span>'}},
    {key:'active',label:'Статус',type:'enum',w:130,val:e=>e.active?'Активен':'Заблокирован',html:e=>e.active?pill('Активен',{Активен:['green','check']}):pill('Заблокирован',{Заблокирован:['red','lock']})},
    can('kbLevels')?{key:'kb',label:'Уровень знаний',type:'enum',w:230,val:e=>{const s=kbFor(e.id);return s.lv[s.cur].n},sortVal:e=>{const s=kbFor(e.id);return s.cur*1000+s.pct},html:e=>kbBadge(kbFor(e.id))}:null,
    {key:'open',label:'Несданных',type:'int',w:110,num:true,val:e=>empStats(e).open,hide:true},{key:'login',label:'Логин',type:'text',w:100,val:e=>e.login,cls:'mono',hide:true},
    {key:'tg',label:'Telegram',type:'enum',w:140,val:e=>e.tg?'Привязан':'Не привязан',html:e=>e.tg?`<span class="pill green sm">${ic('tg')}привязан</span>`:`<span class="pill orange sm">${ic('alert')}не привязан</span>`,hide:true},can('staff')?{key:'bal',label:'Баланс счёта',type:'money',w:140,num:true,total:true,val:e=>empBal(e),hide:true}:null,{key:'lastIn',label:'Последний вход',type:'text',w:150,val:e=>e.lastIn||'',hide:true}].filter(Boolean),
    rows:()=>EMP,title:'fio',noun:['сотрудник','сотрудника','сотрудников'],rowClass:e=>e.active?'':'muted',actions:empActions,open:e=>empCard(e),sort:{key:'fio',dir:1},simulateLoad:fresh});return}
  if(tab==='roles'){body.innerHTML=`<div class="note">${ic('info')}<span>Права выдаются через роли: сотрудник → роль → права. Права разбиты по модулям, под каждым — что оно разрешает. Кнопки и вкладки без права не показываются, а сервер всё равно проверяет право при каждом действии. «Настройки и учётная политика» есть только у владельца; «Откат статусов», «Распоряжаться остатком при архивировании» и «Сотрудники и роли» выдаёт только владелец; права своей роли сотрудник не меняет.</span></div><div id="rg"></div>`;
    grid($('#rg',body),{id:'roles',audit:false,cols:[
      {key:'name',label:'Роль',type:'text',w:240,val:r=>r.name,html:r=>`<span class="strong">${esc(r.name)}</span>${r.locked?' <span class="tag">все права</span>':''}`},
      {key:'emps',label:'Сотрудников',type:'int',w:120,num:true,val:r=>EMP.filter(e=>e.role===r.id&&e.active).length},
      {key:'perms',label:'Прав',type:'int',w:110,num:true,val:r=>roleN(r),html:r=>`${roleN(r)} <span class="faint">из ${PERMS.length}</span>`},
      {key:'_ua',label:'Изменено',type:'datetime',w:150,val:r=>r._ua||null},
      {key:'_ub',label:'Изменил',type:'enum',w:140,val:r=>whoName(r._ub||r._cb),hide:true}],
      rows:()=>ROLES,title:'name',noun:['роль','роли','ролей'],actions:roleActions,open:roleCard,sort:{key:'name',dir:1},simulateLoad:fresh});return}
  if(tab==='bonus'){const boss=can('bonus')&&seeAll('fin');const prev=addMonths(ym(TODAY),-1);const cl=[...CLOSED].sort().reverse();
    body.innerHTML=`<div class="row" style="flex-wrap:wrap"><span class="muted">Ежемесячный отчёт по списаниям. Закрытый месяц фиксирует списания и оплаты: отменить их можно только корректирующей записью.</span><div class="grow"></div>${cl.length?`<span class="tag">${ic('lock','sm')} Закрыты: ${cl.map(ymLabel).join(', ')}</span>`:''}${boss&&!CLOSED.has(prev)?`<button class="btn sm" id="bg-close">${ic('lock','sm')}Закрыть ${esc(ymLabel(prev))}</button>`:''}</div><div id="bg"></div>`;
    if($('#bg-close',body))$('#bg-close',body).onclick=()=>{const n=OPS.filter(o=>o.kind==='bonus'&&ym(o.date)===prev);confirmDlg({title:`Закрыть ${esc(ymLabel(prev))}?`,text:`Списаний за месяц: ${n.length} на ${som(n.reduce((a,o)=>a+o.amount,0))}. После закрытия оплаты налогов и списания этого месяца нельзя отменить — только корректирующей записью.`,ok:'Закрыть месяц',run:()=>{CLOSED.add(prev);log('org','policy',`Месяц ${ymLabel(prev)} закрыт отчётом о списаниях`);renderPage();toast('Месяц закрыт','lock')}})};
    grid($('#bg',body),{id:'bonus',cols:[
    {key:'date',label:'Дата',type:'date',w:110,val:o=>o.date},{key:'month',label:'Месяц',type:'enum',w:130,val:o=>ymLabel(ym(o.date)),sortVal:o=>o.date},
    {key:'emp',label:'Сотрудник',type:'enum',w:150,val:o=>o.holder==='org'?'Счёт организации':empName(o.holder)},{key:'cp',label:'Контрагент',type:'enum',w:220,val:o=>CPM[o.cp].name},
    {key:'sum',label:'Сумма',type:'money',w:130,num:true,total:true,val:o=>o.amount},{key:'note',label:'Причина',type:'text',w:220,val:o=>o.note||''},{key:'by',label:'Списал',type:'enum',w:120,val:o=>empName(o.by)}],
    audit:o=>({_cb:o.by,_ca:o._ca||o.date}),rows:()=>OPS.filter(o=>o.kind==='bonus'),open:o=>opWin({src:'op',ref:o}),actions:o=>[...opActs({src:'op',ref:o}),{sep:true},{label:'Карточка контрагента',icon:'building',run:()=>openCp(CPM[o.cp],'money')}],title:'cp',noun:['списание','списания','списаний'],sort:{key:'date',dir:-1},empty:{icon:'gift',title:'Списаний пока не было'}})}
}
// «Сменить роль», «Заблокировать» не показываются, если сотрудника менять нельзя (empLocked: владелец; не владельцу — он сам и сотрудники с ролями, которые он не назначает). «Сбросить пароль» — только у владельца: право «Сотрудники и роли» пароль не сбрасывает (решение заказчика 30.10.2026, п. 11 «Б»)
function empActions(e){const it=[{label:'Открыть карточку',icon:'user',run:()=>empCard(e)}];if(!empEditOff(e))it.push({label:'Изменить',icon:'edit',run:()=>empEditDlg(e)});
  if(e.role!=='owner'&&can('staff')){it.push({label:'Передать контрагентов',icon:'refresh',disabled:!empStats(e).cps,reason:!empStats(e).cps&&'Нет закреплённых контрагентов',run:()=>transferDlg(e)});if(empLocked(e))return it;
    it.push({label:'Сменить роль',icon:'shield',run:()=>openModal({form:true,render:()=>({title:'Роль сотрудника',sub:esc(e.fio),body:fld('Роль',sel('cr-r',rolesAssignable().map(r=>[r.id,r.name]),e.role),{id:'cr-r',hint:me().role==='owner'?'':'Роли с правами, которые выдаёт только владелец, и роли шире вашей назначает владелец'}),foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="cr-ok">Сохранить</button>',mount(el,m){$('#cr-ok',el).onclick=()=>{const o=e.role,n=val(el,'cr-r');e.role=n;log('emp',e.id,`Роль: ${ROLES.find(x=>x.id===o).name} → ${ROLES.find(x=>x.id===n).name}`);m.close();refreshAll();toast('Роль изменена','shield')}}})})});
    if(me().role==='owner')it.push({label:'Сбросить пароль',icon:'key',run:()=>empResetPass(e)});
    it.push({sep:true});it.push(e.active?{label:'Заблокировать',icon:'lock',danger:true,run:()=>blockDlg(e)}:{label:'Разблокировать',icon:'key',run:()=>{e.active=true;log('emp',e.id,'Разблокирован');refreshAll();toast('Сотрудник разблокирован')}})}
  return it}
// Сброс пароля сотрудника: временный пароль, все сеансы завершаются; если Telegram привязан, бот сообщает о сбросе с ФИО того, кто сбросил (шаблон «Пароль сброшен»)
function empResetPass(e){e.tmpPass=tmpPass();log('emp',e.id,'Пароль сброшен');tgSvc(e,'Пароль сброшен');
  openModal({render:()=>({title:'Пароль сброшен',sub:esc(e.fio),body:`<p style="margin:0">Временный пароль: <b class="mono" style="font-size:16px">${esc(e.tmpPass)}</b></p><p class="muted" style="margin:0">Передайте его сотруднику лично. При первом входе нужно будет задать свой пароль. Все прежние сеансы завершены${e.tg?', бот сообщил о сбросе в Telegram':''}.</p>`,foot:'<button class="btn cta" data-close>Готово</button>'})})}
function transferDlg(e,after){const st=empStats(e);const cps=CPS.filter(c=>c.resp===e.id&&!c.archived);const money=cps.filter(c=>c.paysTo==='emp').reduce((a,c)=>a+c.avail,0);
  const ids=new Set(cps.map(c=>c.id));const unf=REPORTS.filter(r=>ids.has(r.cp)&&repUnfinished(r)&&(r.resp===e.id||!r.resp)).length;const tks=TASKS.filter(t=>ids.has(t.cp)&&t.exec===e.id&&taskOpen(t)).length;const to0=(EMP.find(x=>x.active&&x.id!==e.id&&x.role==='chief')||EMP.find(x=>x.active&&x.id!==e.id)||{}).id;
  openModal({form:true,render:()=>({title:'Передать контрагентов',sub:`от ${esc(e.fio)}`,body:`${fld('Кому',sel('tr-to',EMP.filter(x=>x.active&&x.id!==e.id).map(x=>[x.id,x.short]),to0),{req:true,id:'tr-to'})}<div class="box flat"><h3>Что перейдёт</h3><div class="kv"><div><span class="k">Контрагенты</span><span class="v strong">${st.cps}</span></div><div><span class="k">Незавершённые отчёты</span><span class="v">${unf}</span></div><div><span class="k">Открытые задачи по ним</span><span class="v">${tks}</span></div>${feat('taxpay')?`<div><span class="k">Остаток денег на налоги</span><span class="v tnum">${som(money)}</span></div>`:''}</div><span class="hint">Незавершённые — ещё не сданы или налог не оплачен. Завершённые отчёты останутся за тем, кто их сдал. Передача запишется в историю каждого контрагента.</span></div>`,
    foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="tr-ok">Передать</button>',mount(el,m){$('#tr-ok',el).onclick=()=>{const to=val(el,'tr-to');cps.forEach(c=>transferCp(c,to));m.close();after&&after();refreshAll();toast(`Передано ${cps.length} контрагентов: ${empName(to)}`,'refresh')}}})});
}
function blockDlg(e){const n=empStats(e).cps;
  if(n){confirmDlg({title:`Сначала передайте ${n} ${plural(n,'контрагента','контрагентов','контрагентов')}`,text:`Заблокированный сотрудник не может войти. Его контрагенты, несданные отчёты и открытые задачи нужно передать другому ответственному.`,ok:'Передать и заблокировать',danger:true,run:()=>transferDlg(e,()=>{e.active=false;log('emp',e.id,'Заблокирован')})});return}
  confirmDlg({title:`Заблокировать ${esc(e.short)}?`,text:'Сотрудник не сможет войти. Его история сохранится.',ok:'Заблокировать',danger:true,run:()=>{e.active=false;log('emp',e.id,'Заблокирован');refreshAll();toast('Сотрудник заблокирован','lock')}})}
// «Изменить»: ФИО и телефон (расхождение продукта п. 16, решение заказчика 27.10.2026); логин не меняется, роль — «Сменить роль»
function empEditDlg(e){const mine=e.id===S.me;openModal({form:true,size:'mid',render:()=>({title:'Изменить сотрудника',sub:esc(e.fio),body:`<div class="form">${fld('ФИО',inp('ee-fio',e.fio),{req:true,full:true,id:'ee-fio'})}${fld('Телефон',phoneInput('ee-ph',e.phone||null),{id:'ee-ph'})}</div>`,
  foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="ee-ok">Сохранить</button>',mount(el,m){bindPhone(el,'ee-ph');$('#ee-ok',el).onclick=()=>{const fio=val(el,'ee-fio').trim().replace(/\s+/g,' '),ph=readPhone(el,'ee-ph');
    if(![setErr(el,'ee-fio',fio.split(' ').length>=2?'':'Введите фамилию и имя'),setErr(el,'ee-ph',ph.empty||ph.ok?'':`Номер — ${ph.need} цифр после кода страны`)].every(Boolean))return;
    const nph=ph.empty?null:ph.ph,ch=[];if(fio!==e.fio)ch.push(`ФИО: ${e.fio} → ${fio}`);if((nph||null)!==(e.phone||null))ch.push(`Телефон: ${e.phone?fmtPhone(e.phone):'—'} → ${nph?fmtPhone(nph):'—'}`);
    if(ch.length){e.fio=fio;e.short=fio.split(' ')[1]+' '+fio[0]+'.';e.phone=nph;touch(e);ch.forEach(x=>log('emp',e.id,x))}m.close();refreshAll();if(mine)renderSide();toast('Данные сотрудника сохранены','user')}}})})}
function empCard(e,tab){ckHit('empcard');
  openModal({size:'wide',live:true,state:{tab:tab||'main'},render:m=>{const st=m.state;const s=empStats(e);const tabs=[['main','Основное','user'],['cps','Контрагенты','building'],can('staff')&&feat('accounts')&&feat('taxpay')?['acc','Счёт','wallet']:null].filter(Boolean);let b='';
    if(st.tab==='main')b=`<div class="box"><div class="kv">${auditKv(e)}<div><span class="k">Логин</span><span class="v mono">${esc(e.login)}</span></div><div><span class="k">Телефон</span><span class="v">${phoneHtml(e.phone)}</span></div><div><span class="k">Роль</span><span class="v">${esc(ROLES.find(r=>r.id===e.role).name)}</span></div><div><span class="k">Telegram</span><span class="v">${e.tg?esc(e.tg):'<span class="orange">не привязан</span>'}</span></div><div><span class="k">Последний вход</span><span class="v">${esc(e.lastIn)}</span></div><div><span class="k">Статус</span><span class="v">${e.active?'Активен':'Заблокирован'}</span></div></div></div>
      <div class="plates">${plate({id:'a',icon:'building',color:'blue',label:'Контрагентов',value:s.cps})}${plate({id:'b',icon:'file',color:'yellow',label:'Несданных отчётов',value:s.open})}${plate({id:'c',icon:'alert',color:s.over?'red':'green',label:'Просрочено',value:s.over})}${plate({id:'d',icon:'task',color:'purple',label:'Открытых задач',value:s.tasks})}</div>
      ${can('kbLevels')||e.id===S.me?kbBox(kbFor(e.id),{mods:1}):''}
      ${!can('staff')?'':`<div class="box"><h3>Реквизиты для переводов</h3>${(e.wallets||[]).length?`<table class="mini m-cards"><tbody>${e.wallets.map(w=>`<tr><td>${w.kind==='phone'?ic('phone','sm'):ic('wallet','sm')} ${esc(rqKindL(w))}</td><td>${esc(rqProv(w))}</td><td class="mono">${esc(rqNum(w))}</td><td>${esc(w.name||'')}</td><td>${w.main?'<span class="tag">основной</span>':''}</td></tr>`).join('')}</tbody></table>`:'<span class="faint">Реквизитов нет — сотрудник добавляет их в своём профиле</span>'}</div>`}`;
    if(st.tab==='cps'){const cps=CPS.filter(c=>c.resp===e.id&&!c.archived);b=`<div class="row"><span class="muted">Закреплено контрагентов: ${cps.length}</span><div class="grow"></div>${cps.length&&e.role!=='owner'&&can('staff')?`<button class="btn sm cta" id="ec-tr">${ic('refresh','sm')}Передать контрагентов</button>`:''}</div><div class="box"><table class="mini m-cards"><thead><tr><th>Контрагент</th><th>Режим</th><th class="num">Несданных</th><th class="num">Просрочено</th></tr></thead><tbody>${cps.map(c=>`<tr class="clk" data-cpid="${c.id}"><td>${esc(c.name)}</td><td>${esc(c.regime)}</td><td class="num">${REPORTS.filter(r=>r.cp===c.id&&!r.superseded&&OPEN.has(r.status)).length}</td><td class="num ${c.overdue?'red strong':''}">${c.overdue}</td></tr>`).join('')||'<tr><td class="faint">Нет закреплённых контрагентов</td></tr>'}</tbody></table></div>`}
    if(st.tab==='acc'){const ops=OPS.filter(o=>o.holder===e.id&&OPK[o.kind]);const byCp={};ops.forEach(o=>{const x=byCp[o.cp]=byCp[o.cp]||{in:0,pay:0,bonus:0,out:0};if(o.kind==='in'||o.kind==='back'||o.kind==='corr'||o.kind==='xfer')x.in+=o.amount;else if(o.kind==='pay')x.pay+=o.amount;else if(o.kind==='bonus')x.bonus+=o.amount;else x.out+=o.amount});
      const tot=k=>Object.values(byCp).reduce((a,x)=>a+x[k],0);const bal=tot('in')-tot('pay')-tot('bonus')-tot('out');
      b=`<div class="plates">${plate({id:'1',icon:'wallet',color:'blue',label:'Баланс счёта',value:fmtM(bal,false),unit:'сом'})}${plate({id:'2',icon:'dn',color:'green',label:'Поступления',value:fmtM(tot('in'),false),unit:'сом'})}${plate({id:'3',icon:'up',color:'yellow',label:'Оплаты налогов',value:fmtM(tot('pay'),false),unit:'сом'})}${plate({id:'4',icon:'gift',color:'purple',label:'Накоплено бонусов',value:fmtM(tot('bonus'),false),unit:'сом'})}</div>
      <div class="box"><h3>В разрезе контрагентов</h3><div class="tbl-wrap"><table class="mini m-cards"><thead><tr><th>Контрагент</th><th class="num">Поступило</th><th class="num">Оплачено</th><th class="num">Бонус</th><th class="num">Остаток</th></tr></thead><tbody>${Object.entries(byCp).map(([id,x])=>`<tr class="clk" data-cpid="${id}"><td>${esc(CPM[id].name)}</td><td class="num">${fmtM(x.in)}</td><td class="num">${fmtM(x.pay)}</td><td class="num">${fmtM(x.bonus)}</td><td class="num strong">${fmtM(x.in-x.pay-x.bonus-x.out)}</td></tr>`).join('')||'<tr><td class="faint">Операций нет</td></tr>'}</tbody></table></div><span class="hint">Налог контрагента оплачивается только деньгами этого контрагента; деньги других контрагентов на него не тратятся.</span></div>`}
    return {title:esc(e.fio),sub:`${esc(ROLES.find(r=>r.id===e.role).name)}${e.active?'':' · заблокирован'}`,body:`${cardTabs(tabs,st.tab,'et')}${b}`,
      foot:`${empEditOff(e)?'':`<button class="btn" id="ec-ed">${ic('edit','sm')}Изменить</button>`}${e.role!=='owner'&&can('staff')?`<button class="btn" id="ec-more">${ic('more','sm')}Действия</button>`:''}<div class="grow"></div><button class="btn cta" data-close>Готово</button>`,
      mount(el,mm){bindCardTabs(el,'et',k=>{st.tab=k;mm.draw();const mb=el.querySelector('.mb');if(mb)mb.scrollTop=0});const mo=$('#ec-more',el);if(mo)mo.onclick=ev=>menu(ev.currentTarget,empActions(e).filter(x=>x.label!=='Открыть карточку'&&x.label!=='Изменить'));const ed=$('#ec-ed',el);if(ed)ed.onclick=()=>empEditDlg(e);
        const tr=$('#ec-tr',el);if(tr)tr.onclick=()=>transferDlg(e);$$('[data-cpid]',el).forEach(x=>x.onclick=()=>openCp(CPM[+x.dataset.cpid]))}}}});
}
function empAddDlg(){openModal({form:true,size:'mid',render:()=>({title:'Новый сотрудник',sub:'Вход по логину и паролю, без почты',body:`<div class="form">${fld('ФИО',inp('ne-fio',''),{req:true,full:true,id:'ne-fio'})}${fld('Логин',inp('ne-login','','class="inp mono" autocomplete="off"'),{req:true,id:'ne-login',hint:'Уникален на всей платформе'})}${fld('Временный пароль',inp('ne-pass',tmpPass(),'class="inp mono" autocomplete="off"'),{req:true,id:'ne-pass',hint:'Не короче 8 символов'})}${fld('Телефон',phoneInput('ne-ph'),{id:'ne-ph'})}${fld('Роль',sel('ne-role',rolesAssignable().map(r=>[r.id,r.name]),ORG.defaultRole),{req:true,id:'ne-role',hint:me().role==='owner'?'':'Роли с правами, которые выдаёт только владелец, и роли шире вашей назначает владелец'})}</div><div class="note">${ic('tg')}<span>При первом входе сотруднику предложат привязать Telegram — без него не будет напоминаний и самостоятельного восстановления пароля.</span></div>`,
  foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="ne-ok">Создать</button>',mount(el,m){bindPhone(el,'ne-ph');$('#ne-ok',el).onclick=()=>{const fio=val(el,'ne-fio'),lg=val(el,'ne-login').toLowerCase();const ph=readPhone(el,'ne-ph');
    const ok=[setErr(el,'ne-fio',fio.split(' ').length>=2?'':'Введите фамилию и имя'),setErr(el,'ne-login',!/^[a-z0-9._-]{3,}$/.test(lg)?'Латиница, цифры, точка, дефис; от 3 символов':allUsers().some(u=>u.login===lg)?'Такой логин уже занят на платформе':''),setErr(el,'ne-pass',val(el,'ne-pass').trim().length>=8?'':'Не короче 8 символов'),setErr(el,'ne-ph',ph.empty||ph.ok?'':`Номер — ${ph.need} цифр после кода страны`),setErr(el,'ne-role',val(el,'ne-role')?'':'Нет ролей, которые вы можете назначить')].every(Boolean);if(!ok)return;
    const id='e'+(EMP.length+1);const e={id,fio,short:fio.split(' ')[1]+' '+fio[0]+'.',login:lg,phone:ph.empty?null:ph.ph,role:val(el,'ne-role'),tg:null,active:true,lastIn:'ещё не входил',wallets:[],tmpPass:val(el,'ne-pass').trim()};born(e);EMP.push(e);EM[id]=e;log('emp',id,'Сотрудник создан');m.close();refreshAll();toast('Сотрудник создан','user')}}})})}
function roleAddDlg(){openModal({form:true,render:()=>({title:'Новая роль',body:`${fld('Название',inp('nr-name',''),{req:true,id:'nr-name'})}${fld('Скопировать права из',sel('nr-from',ROLES.map(r=>[r.id,r.name]),'acc'),{id:'nr-from'})}`,foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="nr-ok">Создать</button>',
  mount(el,m){$('#nr-ok',el).onclick=()=>{const n=val(el,'nr-name');if(!setErr(el,'nr-name',n?ROLES.some(r=>r.name===n)?'Такая роль уже есть':'':'Введите название'))return;const nr={id:'r'+ROLES.length,name:n,perms:[...ROLES.find(r=>r.id===val(el,'nr-from')).perms.filter(p=>p!=='org'&&(me().role==='owner'||!OWNER_GRANTS.includes(p)&&myRole().perms.includes(p)))]};born(nr);ROLES.push(nr);log('role',nr.id,`Создана роль «${n}»`);m.close();go('staff','roles');refreshAll();toast('Роль создана: отметьте её права','shield');roleForm(nr)}}})})}


/* ═════════════ Роли: права по группам модулей ═════════════ */
const roleN=r=>r.locked?PERMS.length:r.perms.filter(p=>PERMS.some(x=>x[0]===p)).length;
// «Удалить» — у роли, которая никому не назначена; роль владельца и роль по умолчанию для новых сотрудников не удаляются (расхождение продукта п. 16, решение заказчика 27.10.2026)
function roleDelOff(r){return r.locked||r.id==='owner'?'Роль владельца не удаляется':EMP.some(e=>e.role===r.id)?'Роль назначена сотрудникам: сначала смените им роль':r.id===ORG.defaultRole?'Эту роль получают новые сотрудники: сначала выберите другую в «Моя организация» → «Настройки»':''}
function roleDel(r){confirmDlg({title:`Удалить роль «${esc(r.name)}»?`,text:'Права роли удалятся вместе с ней, вернуть роль будет нельзя.',ok:'Удалить',danger:true,run:()=>{const i=ROLES.indexOf(r);if(i>=0)ROLES.splice(i,1);log('role',r.id,`Удалена роль «${r.name}»`);refreshAll();toast('Роль удалена','trash')}})}
// Роль, которую сотрудник менять не может (своя, с правами «выдаёт только владелец», шире своей), — без «Изменить» и «Удалить»; роль владельца — оба пункта неактивны с причиной
function roleActions(r){const it=[{label:'Открыть',icon:'shield',run:()=>roleCard(r)}];
  if(!can('staff'))return [...it,{label:'Изменить',icon:'edit',disabled:true,reason:'Нет права «Сотрудники и роли»',run:()=>{}}];
  if(r.locked)return [...it,{label:'Изменить',icon:'edit',disabled:true,reason:'Права владельца не меняются',run:()=>{}},{sep:true},{label:'Удалить',icon:'trash',danger:true,disabled:true,reason:roleDelOff(r),run:()=>{}}];
  if(roleAssignOff(r))return it;const d=roleDelOff(r);return [...it,{label:'Изменить',icon:'edit',run:()=>roleForm(r)},{sep:true},{label:'Удалить',icon:'trash',danger:true,disabled:!!d,reason:d,run:()=>roleDel(r)}]}
// Группы прав: o.sel — Set выбранных, o.lock(p) — причина, почему галочка неактивна, o.ro — только просмотр, o.q — поиск, o.tog — Set раскрытых/свёрнутых вручную групп,
// o.scope — область групп с контрагентами {cps:'own'|'all',…}; право «Видеть все отчёты и всех контрагентов» ставит «Все» во всех группах
const scopeOf=(o,g)=>o.sel.has('viewAll')?'all':(o.scope&&o.scope[g])||'own';
function scopeHtml(o,g){if(!g.scope)return '';const v=scopeOf(o,g.id),fixed=o.sel.has('viewAll');
  const off=!o.ro&&!fixed&&o.scOff?o.scOff(g.id):'';
  if(o.ro||fixed)return `<span class="tag pg-sc" title="${fixed?'Задано правом «Видеть все отчёты и всех контрагентов»':'Область'}">${ic(v==='all'?'building':'user','sm')}${v==='all'?'Все контрагенты':'Свои контрагенты'}</span>`;
  return `<div class="seg sm pg-sc" role="group" aria-label="Область"><button type="button" data-psc="${g.id}|own" class="${v==='own'?'on':''}" ${off?'disabled':''}>Свои контрагенты</button><button type="button" data-psc="${g.id}|all" class="${v==='all'?'on':''}" ${off?'disabled':''}>Все контрагенты</button></div>${off?`<span class="pg-why">${ic('lock','sm')} ${esc(off)}</span>`:''}`}
function permGroupsHtml(o){const q=norm(o.q||'');let any=false;
  const html=PERM_GROUPS.map(g=>{const ps=g.perms.filter(p=>!q||norm(p[1]+' '+p[2]).includes(q));if(!ps.length)return '';any=true;
    const off=g.feature&&!feat(g.feature);const n=g.perms.filter(p=>o.sel.has(p[0])).length;const open=q?true:(isMobile()||off)?o.tog.has(g.id):!o.tog.has(g.id);
    const free=g.perms.filter(p=>!o.lock(p[0])||(g.view&&o.lock(p[0])==='Сначала дайте просмотр'));const allOn=free.length&&free.every(p=>o.sel.has(p[0]));
    return `<section class="pg ${open?'open':''} ${off?'off':''}" data-pg="${g.id}"><div class="pg-h"><button type="button" class="pg-t" data-pgt="${g.id}" aria-expanded="${open}"><span class="pg-chev">${ic('right','sm')}</span><b>${esc(g.name)}</b></button><span class="pg-n">Выбрано ${n} из ${g.perms.length}</span>${!o.ro&&free.length?`<button type="button" class="btn sm" data-pall="${g.id}">${allOn?'Снять все':'Выбрать все'}</button>`:''}${g.scope?`<div class="pg-scw"><span class="muted">Область:</span>${scopeHtml(o,g)}</div>`:''}${off?`<span class="pg-off">${ic('lock','sm')} Модуль выключен в учётной политике: права сохранятся и начнут действовать после включения</span>`:''}</div>
      <div class="pg-b">${ps.map(p=>{const why=o.lock(p[0]);const on=o.sel.has(p[0]);const isV=g.view===p[0];return o.ro?`<div class="pg-p ro ${on?'':'no'} ${isV?'pg-v':''}"><span class="pg-x ${on?'green':'faint'}">${ic(on?'check':'x','sm')}</span><span><b>${esc(p[1])}</b><span class="pg-d">${esc(p[2])}</span></span></div>`
        :`<label class="pg-p ${isV?'pg-v':''}"><input type="checkbox" data-pp="${p[0]}" ${on?'checked':''} ${why?'disabled':''} aria-label="${esc(p[1])}"><span><b>${esc(p[1])}</b><span class="pg-d">${esc(p[2])}</span>${why?`<span class="pg-why">${ic('lock','sm')} ${esc(why)}</span>`:''}</span></label>`}).join('')}</div></section>`}).join('');
  return any?`<div class="pg-grid">${html}</div>`:'<div class="faint">Ничего не найдено</div>'}
// Привязка формы прав: клики по заголовку группы, «Выбрать все» (вместе с просмотром), галочки, область, поиск; draw — перерисовка окна
function permGroupsBind(el,o,draw){el.querySelectorAll('[data-pgt]').forEach(b=>b.onclick=()=>{const id=b.dataset.pgt;o.tog.has(id)?o.tog.delete(id):o.tog.add(id);draw()});
  el.querySelectorAll('[data-pall]').forEach(b=>b.onclick=()=>{const g=PERM_GROUPS.find(x=>x.id===b.dataset.pall);const fr=()=>g.perms.filter(p=>!o.lock(p[0]));
    const on=b.textContent.trim()==='Снять все';if(on)fr().forEach(p=>o.sel.delete(p[0]));else{if(g.view&&!o.lock(g.view))o.sel.add(g.view);fr().forEach(p=>o.sel.add(p[0]))}draw()});
  el.querySelectorAll('[data-pp]').forEach(c=>c.onchange=()=>{c.checked?o.sel.add(c.dataset.pp):o.sel.delete(c.dataset.pp);draw()});
  el.querySelectorAll('[data-psc]').forEach(b=>b.onclick=()=>{const[g,v]=b.dataset.psc.split('|');o.scope=o.scope||{};o.scope[g]=v;draw()});
  const qs=el.querySelector('#pg-q');if(qs){qs.oninput=()=>{o.q=qs.value;draw();const n=el.querySelector('#pg-q');if(n){n.focus();n.setSelectionRange(n.value.length,n.value.length)}}}}
const pgSearch=o=>`<input class="inp" id="pg-q" type="search" placeholder="Поиск по названию и описанию права" value="${esc(o.q||'')}" aria-label="Поиск права">`;
function roleCard(r){ckHit('roles');const o={sel:new Set(r.locked?PERMS.map(p=>p[0]):r.perms),scope:roleScope(r),lock:()=>'',ro:true,q:'',tog:new Set()};
  openModal({size:'wide',live:true,render:m=>{const why=can('staff')&&!r.locked?roleAssignOff(r):'';return {title:esc(r.name),sub:`${EMP.filter(e=>e.role===r.id&&e.active).length} чел. · прав ${roleN(r)} из ${PERMS.length}`,body:`${r.locked?`<div class="note">${ic('lock')}<span>У владельца организации все права, они не меняются.</span></div>`:why?`<div class="note">${ic('lock')}<span>Только для чтения: ${esc(why[0].toLowerCase()+why.slice(1))}.</span></div>`:''}${pgSearch(o)}${permGroupsHtml(o)}`,
    foot:`${can('staff')&&!r.locked&&!why?`<button class="btn" id="rc-ed">${ic('edit','sm')}Изменить</button>`:''}<div class="grow"></div><button class="btn cta" data-close>Готово</button>`,
    mount(el){permGroupsBind(el,o,()=>m.draw());const b=$('#rc-ed',el);if(b)b.onclick=()=>{m.close();roleForm(r)}}}}})}
function roleForm(r){const o={sel:new Set(r.perms),scope:roleScope(r),q:'',tog:new Set(),scOff:roleScopeOff};o.lock=p=>roleLock(r,p,o.sel);let name=r.name;
  openModal({form:true,size:'wide',live:true,render:m=>({title:'Права роли',sub:esc(r.name),body:`${fld('Название роли',inp('rf-name',name),{req:true,id:'rf-name'})}${pgSearch(o)}${permGroupsHtml(o)}`,
    foot:`<span class="hint">Выбрано прав: ${o.sel.size} из ${PERMS.length}</span><div class="grow"></div><button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="rf-ok">Сохранить</button>`,
    mount(el){const nm=$('#rf-name',el);nm.oninput=()=>name=nm.value;permGroupsBind(el,o,()=>m.draw());
      $('#rf-ok',el).onclick=()=>{const n=name.trim();if(!setErr(el,'rf-name',!n?'Введите название':ROLES.some(x=>x!==r&&x.name===n)?'Такая роль уже есть':''))return;
        const add=[...o.sel].filter(p=>!r.perms.includes(p)&&!o.lock(p)),del=r.perms.filter(p=>!o.sel.has(p)&&!o.lock(p));const pn=k=>(PERMS.find(p=>p[0]===k)||[])[1]||k;
        const chg=add.length||del.length||n!==r.name;if(n!==r.name){log('role',r.id,`Роль переименована: «${r.name}» → «${n}»`);r.name=n}
        add.forEach(p=>log('role',r.id,`${r.name}: добавлено право «${pn(p)}»`));del.forEach(p=>log('role',r.id,`${r.name}: снято право «${pn(p)}»`));
        const sc=SCOPE_GROUPS.filter(g=>roleScope(r)[g]!==o.scope[g]);const scN=g=>PERM_GROUPS.find(x=>x.id===g).name;sc.forEach(g=>log('role',r.id,`${r.name}: область «${scN(g)}» — ${o.scope[g]==='all'?'«Все контрагенты»':'«Свои контрагенты»'}`));r.scope=Object.assign({},o.scope);
        r.perms=r.perms.filter(p=>!del.includes(p)).concat(add);if(chg||sc.length)touch(r);m.close();refreshAll();renderSide();toast('Права роли сохранены','shield')}}})})}
